"""Falsifier for C0024 -- bench/cdsfl_registry/engine.py does not pass ruff.

Claim: in its pristine state the target emits 7 ruff errors on defaults --
six F401 (copy, pathlib.Path, typing.Sequence, tomli, .registry.PolicyViolationError,
.registry._check_monotonicity) and one F541 (f-string without placeholders at the
`f"Schema validation errors:\n"` concatenation).

Fires (AssertionError + FALSIFIED) iff those lint defects are genuinely present in
the real module file on disk. Exits clean if absent.
"""
from __future__ import annotations

import ast
import hashlib
import importlib.util
import io
import json
import os
import shutil
import subprocess
import sys
import tokenize
from pathlib import Path

REL = os.path.join("bench", "cdsfl_registry", "engine.py")


def locate_target() -> Path:
    """Resolve the REAL engine.py: package spec first, then upward search."""
    roots = [Path.cwd(), Path(__file__).resolve().parent]
    for r in list(roots):
        roots.extend(r.parents)
    for r in roots:
        if (r / REL).is_file() and str(r) not in sys.path:
            sys.path.insert(0, str(r))
            break
    try:
        spec = importlib.util.find_spec("bench.cdsfl_registry.engine")
        if spec and spec.origin and Path(spec.origin).is_file():
            return Path(spec.origin).resolve()
    except Exception:
        pass
    for r in roots:
        cand = r / REL
        if cand.is_file():
            return cand.resolve()
    raise SystemExit("INCONCLUSIVE: could not locate bench/cdsfl_registry/engine.py")


def repo_root(target: Path) -> Path:
    return target.parent.parent.parent


# --------------------------------------------------------------------------
# Path A: the real linter, exactly as the finding ran it (repo config, or
# defaults when no config exists).
# --------------------------------------------------------------------------
def ruff_errors(target: Path, root: Path):
    exe = shutil.which("ruff")
    if not exe:
        return None
    proc = subprocess.run(
        [exe, "check", "--output-format", "json", str(target)],
        cwd=str(root), capture_output=True, text=True,
    )
    try:
        rows = json.loads(proc.stdout or "[]")
    except json.JSONDecodeError:
        return None
    return [
        (r["code"], r["location"]["row"], r["location"]["column"],
         r.get("message", ""))
        for r in rows
        if r.get("code") in ("F401", "F541")
    ]


# --------------------------------------------------------------------------
# Path B: self-contained replication of F401 / F541 via ast + tokenize, so the
# verdict does not depend on ruff being installed in this environment.
# --------------------------------------------------------------------------
def noqa_lines(src: str) -> set[int]:
    out = set()
    try:
        toks = tokenize.generate_tokens(io.StringIO(src).readline)
        for tok in toks:
            if tok.type == tokenize.COMMENT and "noqa" in tok.string.lower():
                out.add(tok.start[0])
    except tokenize.TokenError:
        pass
    return out


def static_errors(src: str):
    tree = ast.parse(src)
    skip = noqa_lines(src)

    imports = []          # (bound_name, reported_name, lineno, col)
    import_spans = []     # (start_line, end_line)
    for node in ast.walk(tree):
        if isinstance(node, (ast.Import, ast.ImportFrom)):
            import_spans.append((node.lineno, node.end_lineno or node.lineno))
            if isinstance(node, ast.ImportFrom) and node.module == "__future__":
                continue
            for alias in node.names:
                if alias.name == "*":
                    continue
                bound = (alias.asname or alias.name).split(".")[0]
                if isinstance(node, ast.ImportFrom):
                    reported = f"{'.' * node.level}{node.module or ''}.{alias.name}"
                else:
                    reported = alias.name
                imports.append((bound, reported, node.lineno, node.col_offset))

    # every NAME token that is not inside an import statement counts as a use
    used: set[str] = set()
    try:
        for tok in tokenize.generate_tokens(io.StringIO(src).readline):
            if tok.type != tokenize.NAME:
                continue
            row = tok.start[0]
            if any(a <= row <= b for a, b in import_spans):
                continue
            used.add(tok.string)
    except tokenize.TokenError:
        pass
    # names re-exported through __all__ are used
    for node in ast.walk(tree):
        if isinstance(node, ast.Assign) and any(
            isinstance(t, ast.Name) and t.id == "__all__" for t in node.targets
        ):
            for el in getattr(node.value, "elts", []):
                if isinstance(el, ast.Constant) and isinstance(el.value, str):
                    used.add(el.value)

    # a name rebound by a later import (try/except fallback) is only reported
    # at its final binding, matching ruff
    last = {}
    for bound, _r, line, _c in imports:
        last[bound] = max(last.get(bound, 0), line)

    errs = []
    for bound, reported, line, col in imports:
        if line != last[bound]:
            continue
        if bound not in used and line not in skip:
            errs.append(("F401", line, col + 1, f"`{reported}` imported but unused"))

    for node in ast.walk(tree):
        if isinstance(node, ast.JoinedStr):
            if not any(isinstance(v, ast.FormattedValue) for v in node.values):
                if node.lineno not in skip:
                    errs.append(("F541", node.lineno, node.col_offset + 1,
                                 "f-string without any placeholders"))
    return sorted(errs, key=lambda e: (e[1], e[2]))


def main() -> None:
    target = locate_target()
    root = repo_root(target)

    # SNAPSHOT: prove the analysis is read-only -- the target must be byte
    # identical afterwards, so nothing below can have manufactured the verdict.
    before = target.read_bytes()
    digest_before = hashlib.sha256(before).hexdigest()
    src = before.decode("utf-8")

    print(f"target      : {target}")
    print(f"repo root   : {root}")
    print(f"sha256      : {digest_before[:16]}")

    # Premise of the finding: nothing suppresses these rules via config.
    cfgs = [c for c in ("pyproject.toml", ".ruff.toml", "ruff.toml",
                        "setup.cfg", "mypy.ini") if (root / c).is_file()]
    print(f"lint configs: {cfgs or 'none'}")

    live = ruff_errors(target, root)
    static = static_errors(src)
    print(f"ruff        : {'unavailable' if live is None else live}")
    print(f"static F-chk: {static}")

    verdict = live if live is not None else static

    expected = {
        ("F401", 39, 8, "copy"),
        ("F401", 41, 21, "pathlib.Path"),
        ("F401", 42, 47, "typing.Sequence"),
        ("F401", 47, 21, "tomli"),
        ("F401", 55, 5, "PolicyViolationError"),
        ("F401", 58, 5, "_check_monotonicity"),
        ("F541", 201, 13, ""),
    }

    f401 = [e for e in verdict if e[0] == "F401"]
    f541 = [e for e in verdict if e[0] == "F541"]

    # Which of the specifically-named claims are corroborated (match on
    # rule + offending symbol, so line drift after an edit does not matter).
    hit = []
    for code, _, _, sym in sorted(expected):
        if code == "F541":
            if f541:
                hit.append("F541 f-string-without-placeholders")
        else:
            if any(sym.split(".")[-1] in e[3] for e in f401):
                hit.append(f"F401 {sym}")

    target_after = target.read_bytes()
    assert hashlib.sha256(target_after).hexdigest() == digest_before, \
        "falsifier mutated the target -- verdict void"

    if verdict:
        for code, row, col, msg in verdict:
            print(f"  {target.name}:{row}:{col}  {code} {msg}")
        print(f"corroborated: {hit}")
        print("FALSIFIED")
        raise AssertionError(
            f"C0024 confirmed: engine.py fails ruff on defaults -- "
            f"{len(f401)} F401 + {len(f541)} F541 = {len(verdict)} errors "
            f"(claim named 6 F401 + 1 F541); configs present: {cfgs or 'none'}"
        )

    print("clean: no F401/F541 in engine.py -- claim C0024 not reproduced")


if __name__ == "__main__":
    main()

# FALSIFIER C0045 — list_parameters() never validates constraint_class; an
# unrecognised value silently filters everything out, so a caller is told
# there are no HARD parameters when there are 17.
import os, shutil, sys, tempfile, warnings
from pathlib import Path

def _root():
    for c in [Path(os.environ.get("CDSFL_ROOT", ".")), Path.cwd(), *Path.cwd().parents,
              Path("/private/var/folders/cc/scptwd_s4cgclnjn5937fyjw0000gn/T/cdsfl_sim.1VAxrWgWUK/run")]:
        try:
            if (c / "bench" / "cdsfl_registry" / "engine.py").is_file():
                return c.resolve()
        except (OSError, ValueError):
            continue
    raise SystemExit("cannot locate bench/cdsfl_registry/engine.py")

sys.path.insert(0, str(_root()))
from bench.cdsfl_registry import engine, registry

e = engine.PolicyEngine()
real = len(e.list_parameters(constraint_class="HARD"))
assert real == e.parameter_count()["HARD"] > 0, "setup guard: %r" % real

silent = {}
for bad in ("hard", "Hard", "HARD ", "SOFT\t", "TYPO"):
    try:
        got = e.list_parameters(constraint_class=bad)
    except ValueError:
        continue          # rejected — the caller is told
    if not got:
        silent[bad] = len(got)

if silent:
    raise AssertionError(
        "FALSIFIED: list_parameters() answered 'no such parameters' for %d "
        "unrecognised constraint_class values %r, while %d HARD parameters "
        "exist. parameter_count() -> %r"
        % (len(silent), sorted(silent), real, e.parameter_count())
    )
print("QUIET: unrecognised constraint_class values are rejected")

"""C0026 falsifier: engine.py carries gate-blocking dead import bindings.

Fires iff the real bench/cdsfl_registry/engine.py binds module-level imports
that no executable path or annotation ever references -- each one an F401 that
the ruff leg of the fix-admission gate fails on, in-file and in-scope.

The mypy errors (registry.py:32, :194) are PRINTED as context, not asserted:
they live outside the target and no engine.py-scoped edit can reach them.
"""
import ast, json, subprocess, sys
from pathlib import Path


def find_root():
    starts = [Path.cwd()]
    try:
        starts.append(Path(__file__).resolve().parent)
    except NameError:
        pass
    for base in starts:
        p = base.resolve()
        for _ in range(10):
            if (p / "bench" / "cdsfl_registry" / "engine.py").is_file():
                return p
            if p.parent == p:
                break
            p = p.parent
    return None


ROOT = find_root()
assert ROOT is not None, "could not locate bench/cdsfl_registry/engine.py"
sys.path.insert(0, str(ROOT))
from bench.cdsfl_registry import engine as ENG          # absolute import, real package
TARGET = Path(ENG.__file__).resolve()
rel = str(TARGET.relative_to(ROOT))
print(f"[ctx] target = {TARGET}")

# --- exercise the REAL public API; snapshot the schema before the calls ------
before_schema = dict(ENG.PolicyEngine().schema)
eng = ENG.PolicyEngine()
exercised = []
for call, fn in (
    ("validate", lambda: eng.validate()),
    ("query", lambda: eng.query(domain="mathematics")),
    ("list_parameters", lambda: eng.list_parameters()),
    ("parameter_count", lambda: eng.parameter_count()),
):
    try:
        fn()
        exercised.append(call)
    except Exception as exc:
        exercised.append(f"{call}!{type(exc).__name__}")
after_schema = dict(eng.schema)
assert before_schema.keys() == after_schema.keys(), "schema mutated by API exercise"
print(f"[ctx] exercised real API: {exercised} "
      f"({len(after_schema)} params, schema unmutated)")

# --- AST: module-level import bindings never referenced anywhere -------------
src = TARGET.read_text()
tree = ast.parse(src)
bindings = {}
import_nodes = set()
for node in ast.walk(tree):
    if isinstance(node, (ast.Import, ast.ImportFrom)):
        import_nodes.add(node)
        if isinstance(node, ast.ImportFrom) and node.module == "__future__":
            continue
        for a in node.names:
            if a.name == "*":
                continue
            bound = a.asname or a.name.split(".")[0]
            bindings[bound] = (node.lineno, ast.unparse(node).split("\n")[0][:60])

referenced = set()
for node in ast.walk(tree):
    if node in import_nodes:
        continue
    if isinstance(node, ast.Name):
        referenced.add(node.id)
    elif isinstance(node, ast.Attribute):
        base = node
        while isinstance(base, ast.Attribute):
            base = base.value
        if isinstance(base, ast.Name):
            referenced.add(base.id)
    elif isinstance(node, ast.Constant) and isinstance(node.value, str):
        # `from __future__ import annotations` stringifies hints at runtime;
        # also catch names that only ever appear inside a string annotation.
        try:
            for sub in ast.walk(ast.parse(node.value, mode="eval")):
                if isinstance(sub, ast.Name):
                    referenced.add(sub.id)
        except SyntaxError:
            pass
for name in getattr(ENG, "__all__", []) or []:
    referenced.add(name)

dead = sorted((ln, n, d) for n, (ln, d) in bindings.items() if n not in referenced)
print(f"[ctx] {len(bindings)} import bindings, {len(dead)} never referenced")

# --- corroborate with the gate's own tools (advisory, never the assertion) ---
def run(cmd):
    try:
        return subprocess.run(cmd, cwd=ROOT, capture_output=True,
                              text=True, timeout=300)
    except (FileNotFoundError, subprocess.TimeoutExpired):
        return None

r = run([sys.executable, "-m", "ruff", "check", "--output-format=json", rel])
if r is not None and r.stdout.strip().startswith("["):
    diags = json.loads(r.stdout)
    in_scope = [d for d in diags
                if (ROOT / d["filename"]).resolve() == TARGET]
    print(f"[ctx] ruff: {len(diags)} diagnostics, {len(in_scope)} inside the "
          f"target ({sorted({d['code'] for d in in_scope})})")
m = run([sys.executable, "-m", "mypy", rel])
if m is not None and m.stdout:
    errs = [l for l in m.stdout.splitlines() if ": error:" in l]
    foreign = [l for l in errs if not l.startswith(rel)]
    print(f"[ctx] mypy: {len(errs)} errors, {len(foreign)} located OUTSIDE the "
          f"target (unreachable from an engine.py-scoped fix)")
    for l in foreign:
        print(f"       {l}")

# --- the assertion ----------------------------------------------------------
if dead:
    for ln, name, desc in dead:
        print(f"FALSIFIED: {rel}:{ln}: '{name}' imported but never "
              f"referenced  ({desc})")
    raise AssertionError(
        f"C0026: {rel} carries {len(dead)} dead import binding(s) "
        f"({', '.join(n for _, n, _ in dead)}) -- each is an F401 that the "
        f"ruff leg of the fix-admission gate fails on, in-file and in-scope."
    )
print("CLEAN: no dead import bindings in the target; ruff's F401 leg is unblocked.")

from unittest.mock import patch
from bench.evidence import EvidenceStore

class FakeChain:
    @property
    def records(self):
        return []

    @property
    def epochs(self):
        return []

with patch("bench.evidence.VerificationChain.load_json", return_value=FakeChain()):
    store = EvidenceStore.from_chain_file("experiment_chain.json")
    observed = store.summary().experiment

if observed == "":
    print("FALSIFIED: from_chain_file infers empty experiment for cwd-relative chain file")

"""Falsifier C0028 -- BUILD_BOT_TEST_BENCH_FIX_SPEC.md

Claim under test: the Scope block names three patchable files, while Sec.1C
imposes an eight-key contract on the `benchmark_meta` envelope. That envelope
has a SECOND writer in the same package -- bench/run_experiment.py, which
imports its harness entry points from the in-Scope run_benchmark.py -- and
Scope does not list it. It omits mandated keys, so Sec.1C is unenforceable
as scoped: the only writer the spec may patch is already compliant, and the
non-compliant one is off-limits.

Both halves of the contract are recomputed from the document text; the
writer census is recomputed from the repo by AST.
"""
import ast
import pathlib
import re

DOC = pathlib.Path("bench/BUILD_BOT_TEST_BENCH_FIX_SPEC.md")
BENCH = DOC.parent
text = DOC.read_text(encoding="utf-8")

# --- 1. the Scope block's patchable-file list, from the document ----------
scope_m = re.search(r"^## Scope\n(.*?)(?=^## )", text, re.S | re.M)
assert scope_m, "Scope block not found"
scope_files = set(re.findall(r"^-\s*`([^`]+)`", scope_m.group(1), re.M))
assert scope_files, "no files parsed from Scope block"

# --- 2. the Sec.1C mandated envelope keys, from the document --------------
c_m = re.search(
    r"`benchmark_meta` should include at least:\n((?:^-\s*`.*\n?)+)", text, re.M
)
assert c_m, "Sec.1C benchmark_meta key list not found"
mandated = {
    km.group(1)
    for line in c_m.group(1).splitlines()
    if (km := re.match(r"^-\s*`([^`]+)`", line.strip()))
}
assert len(mandated) == 8, f"expected 8 mandated keys, parsed {sorted(mandated)}"


def literal_keys(node, tree):
    """String keys of a dict literal, resolving one level of Name alias."""
    if isinstance(node, ast.Name):
        best = None
        for n in ast.walk(tree):
            if isinstance(n, ast.Assign):
                targets = n.targets
            elif isinstance(n, ast.AnnAssign):
                targets = [n.target]
            else:
                continue
            if not isinstance(n.value, ast.Dict):
                continue
            if any(isinstance(t, ast.Name) and t.id == node.id for t in targets):
                if n.lineno <= node.lineno and (best is None or n.lineno > best.lineno):
                    best = n
        node = best.value if best is not None else None
    if not isinstance(node, ast.Dict):
        return None
    return {k.value for k in node.keys
            if isinstance(k, ast.Constant) and isinstance(k.value, str)}


# --- 3. census of every benchmark_meta writer in the bench tree -----------
writers = []
for py in sorted(BENCH.rglob("*.py")):
    try:
        src = py.read_text(encoding="utf-8")
    except (OSError, UnicodeDecodeError):
        continue
    if "benchmark_meta" not in src:
        continue
    try:
        tree = ast.parse(src)
    except SyntaxError:
        continue
    for n in ast.walk(tree):
        if not isinstance(n, ast.Dict):
            continue
        for k, v in zip(n.keys, n.values):
            if not (isinstance(k, ast.Constant) and k.value == "benchmark_meta"):
                continue
            keys = literal_keys(v, tree)
            if keys is None:          # not a resolvable literal -- can't judge
                continue
            writers.append((py.relative_to(BENCH.parent).as_posix(),
                            k.lineno, mandated - keys))

# Guards: the census must be non-vacuous and the contract satisfiable,
# otherwise a quiet exit would prove nothing.
assert len(writers) >= 2, f"expected >=2 resolvable benchmark_meta writers, got {writers}"
assert any(not miss and rel in scope_files for rel, _, miss in writers), (
    "no in-Scope writer is Sec.1C-complete; this falsifier is not measuring "
    "the scope asymmetry it claims to"
)

offenders = [(r, l, sorted(m)) for r, l, m in writers if m and r not in scope_files]

if offenders:
    print("Scope block names:", sorted(scope_files))
    print("Sec.1C mandates  :", sorted(mandated))
    for rel, line, missing in writers:
        tag = "in-Scope" if rel in scope_files else "OUT-OF-SCOPE"
        print(f"  {tag:12} {rel}:{line} missing={sorted(missing) or 'none'}")
    raise AssertionError(
        "FALSIFIED: Sec.1C imposes an 8-key benchmark_meta contract, but "
        f"{len(offenders)} writer(s) of that envelope lie outside the Scope "
        "block and violate it -- the contract cannot be enforced as scoped: "
        + "; ".join(f"{r}:{l} omits {m}" for r, l, m in offenders)
    )
print("clean: every benchmark_meta writer is either in Scope or Sec.1C-complete")
